'use strict';
const $=id=>document.getElementById(id);
let players=[],word='',imposter=-1,current=0,revealed=false,phase='setup';
const escapeHtml=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function randomIndex(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n}
function updateNames(){const n=Number($('count').value);if(!Number.isSafeInteger(n)||n<3){$('error').textContent='Bitte eine ganze Spielerzahl ab 3 eingeben.';return}const old=[...$('names').querySelectorAll('input')].map(x=>x.value);const fragment=document.createDocumentFragment();for(let i=0;i<n;i++){const wrap=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input');input.id='name-'+i;input.value=old[i]||'';input.placeholder='Name '+(i+1);input.maxLength=60;input.required=true;input.autocomplete='off';input.dir='auto';input.enterKeyHint='next';label.htmlFor=input.id;label.textContent='Spieler '+(i+1);wrap.append(label,input);fragment.append(wrap)}$('names').replaceChildren(fragment);$('error').textContent='';$('minus').disabled=n<=3}
$('count').addEventListener('change',updateNames);
for(const [id,d] of [['minus',-1],['plus',1]])$(id).onclick=()=>{const n=Number($('count').value);$('count').value=Math.max(3,(Number.isSafeInteger(n)?n:3)+d);updateNames()};
$('showword').onclick=()=>{const hidden=$('word').type==='password';$('word').type=hidden?'text':'password';$('showword').textContent=hidden?'Verbergen':'Zeigen';$('showword').setAttribute('aria-label',hidden?'Wort verbergen':'Wort anzeigen')};
$('form').onsubmit=e=>{e.preventDefault();const n=Number($('count').value),inputs=[...$('names').querySelectorAll('input')];if(inputs.length!==n){updateNames();$('error').textContent='Bitte die Namen für die gewählte Spielerzahl ergänzen.';return}players=inputs.map(x=>x.value.trim());word=$('wordmode').value==='random'?pickWord():$('word').value.trim();if(players.some(x=>!x)||!word){$('error').textContent='Bitte alle Namen und ein Wort eingeben.';return}if(new Set(players.map(x=>x.toLocaleLowerCase('de'))).size!==players.length){$('error').textContent='Bitte eindeutige Namen verwenden, zum Beispiel Alex 1 und Alex 2.';return}start()};
function pickWord(){const pair=WORD_PAIRS[randomIndex(WORD_PAIRS.length)];return $('language').value==='de'?pair[0]:$('language').value==='ar'?pair[1]:pair[0]+' / '+pair[1]}
function updateWordMode(){const custom=$('wordmode').value==='custom';$('customsettings').classList.toggle('hidden',!custom);$('randomsettings').classList.toggle('hidden',custom);$('word').required=custom}
$('wordmode').addEventListener('change',updateWordMode);updateWordMode();
function start(){document.activeElement?.blur?.();imposter=randomIndex(players.length);current=0;revealed=false;phase='roles';$('word').value='';$('word').type='password';$('showword').textContent='Zeigen';$('setup').classList.add('hidden');$('game').classList.remove('hidden');render();window.scrollTo(0,0)}
function render(){const game=$('game');if(phase==='roles'){game.innerHTML=`<div class="panel gamepanel"><span class="eyebrow">ROLLE ${current+1} VON ${players.length}</span><div class="progress"><span style="width:${current/players.length*100}%"></span></div><h2>${escapeHtml(players[current])}, du bist dran.</h2><p>${revealed?'Merke dir deine Rolle. Dann verdecke sie, bevor du das Handy weitergibst.':'Nur du darfst jetzt auf den Bildschirm schauen.'}</p>${revealed?`<div class="secret ${current===imposter?'imposter':''}"><span class="eyebrow">${current===imposter?'DEINE ROLLE':'DEIN GEHEIMES WORT'}</span><strong dir="auto">${current===imposter?'Du bist der Imposter':escapeHtml(word)}</strong><p>${current===imposter?'Hör gut zu und bluffe mit.':'Gib einen Hinweis, ohne das Wort zu nennen.'}</p></div>`:'<div class="secret"><p>Deine Rolle ist verdeckt.</p></div>'}<button class="primary" id="role">${revealed?'Verdecken & weitergeben':'Meine Rolle ansehen'}</button></div>`;$('role').onclick=()=>{if(!revealed)revealed=true;else{revealed=false;current++;if(current===players.length)phase='discussion'}render()}}else if(phase==='discussion'){game.innerHTML=`<div class="panel gamepanel"><span class="eyebrow">ALLE ROLLEN VERTEILT</span><h2>Wer blufft?</h2><p><strong dir="auto">${escapeHtml(players[randomIndex(players.length)])}</strong> beginnt. Nennt reihum einen Hinweis. Verratet das Wort nicht!</p><div class="list">${players.map(p=>`<span class="chip">${escapeHtml(p)}</span>`).join('')}</div><p>Diskutiert und stimmt gemeinsam ab. Deckt erst danach auf.</p><button class="primary" id="finish">Abstimmung beendet – aufdecken</button></div>`;$('finish').onclick=()=>{phase='result';render()}}else{game.innerHTML=`<div class="panel gamepanel"><span class="eyebrow">DIE AUFLÖSUNG</span><h2>${escapeHtml(players[imposter])}<br>war der Imposter.</h2><div class="secret"><span class="eyebrow">DAS GEHEIME WORT</span><strong dir="auto">${escapeHtml(word)}</strong></div><button class="primary" id="restart">Neue Runde einrichten</button></div>`;$('restart').onclick=()=>{word='';imposter=-1;players=[];phase='setup';game.replaceChildren();game.classList.add('hidden');$('setup').classList.remove('hidden');$('count').focus()}}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&phase==='roles'&&revealed){revealed=false;render()}});
updateNames();

function resizeKeyboardSpace(){const viewport=window.visualViewport;const gap=viewport?Math.max(0,window.innerHeight-viewport.height-viewport.offsetTop):0;document.documentElement.style.setProperty('--keyboard-space',gap+'px')}
window.visualViewport?.addEventListener('resize',resizeKeyboardSpace);window.visualViewport?.addEventListener('scroll',resizeKeyboardSpace);
document.addEventListener('focusin',e=>{if(e.target.matches('input,select')){document.body.classList.add('editing');resizeKeyboardSpace();setTimeout(()=>e.target.scrollIntoView({block:'center',behavior:'smooth'}),300)}});
document.addEventListener('focusout',()=>setTimeout(()=>{if(!document.activeElement?.matches('input,select'))document.body.classList.remove('editing')},100));

